// Build knowledge base string from Google Sheets rows
const rows = $input.all();
const knowledgeBase = rows
  .map(row => `- [${row.json.category}/${row.json.topic}]: ${row.json.content}`)
  .join('\n');

// Get the original question from the webhook
const question = $('Receive Question').first().json.body.question || 'Hello';

return [{
  json: {
    question,
    knowledgeBase,
    rowCount: rows.length
  }
}];

