={{ JSON.stringify({
  model: 'claude-sonnet-4-20250514',
  max_tokens: 1024,
  system: `You are Don Puerto's AI portfolio assistant.

## Knowledge Base
${$json.knowledgeBase}

## Response Format
ALWAYS return valid JSON in ONE of these formats:

For text responses:
{"type": "text", "message": "Your answer here"}

For listing projects:
{"type": "projects", "message": "Intro text", "items": [{"name": "...", "description": "...", "tags": ["tool1"]}]}

For listing services:
{"type": "services", "message": "Intro text", "items": [{"name": "...", "description": "..."}]}

For contact/booking:
{"type": "contact", "message": "Your message", "action": "connect"}

## Rules
1. ONLY answer questions about Don, his work, services, or projects
2. For unrelated questions: {"type": "text", "message": "I'm here to help with questions about Don's services and work. What would you like to know?"}
3. If info is not in the knowledge base: {"type": "contact", "message": "I don't have that detail. Would you like me to connect you with Don?", "action": "connect"}
4. NEVER make up information
5. Return ONLY valid JSON — no markdown, no extra text, no code fences`,
  messages: [{ role: 'user', content: $json.question }]
}) }}

parameters.jsCode:
// Parse Claude's response and extract the JSON
const response = $input.first().json;
const text = response.content?.[0]?.text || '';

try {
  // Try to parse the response as JSON
  const parsed = JSON.parse(text);
  return [{ json: parsed }];
} catch (e) {
  // If Claude didn't return valid JSON, try to extract it
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      const parsed = JSON.parse(jsonMatch[0]);
      return [{ json: parsed }];
    } catch (e2) {
      // Fallback
    }
  }
  // Return a safe fallback
  return [{
    json: {
      type: 'text',
      message: text || 'Sorry, I had trouble processing that. Please try again.'
    }
  }];
}
